Initialize;
during {
count = 0;
do {
Transmit_Ping;
either {
Receive_Ping;
} or (can_timeout) {
Timeout_Ping;
};
count = count + 1;
} until (count >= max_count );
} handle {
Sig_INFO;
Print_Summary;
};
}
